const topic = $('On form submission').first().json.topic;
const papers = $('OpenAlex Papers').first().json.results;
const trend = $('OpenAlex Trend').first().json.group_by;

// OpenAlex dă abstractul ca "inverted index" -> îl reconstruim în text
function rebuildAbstract(inv) {
  if (!inv) return '';
  const words = [];
  for (const [word, positions] of Object.entries(inv)) {
    for (const p of positions) words[p] = word;
  }
  return words.join(' ');
}

// Top instituții după numărul de articole
const instCount = {};
for (const p of papers) {
  const seen = new Set();
  for (const a of p.authorships ?? []) {
    for (const inst of a.institutions ?? []) {
      if (inst.type === 'company') continue;
      if (!seen.has(inst.display_name)) {
        seen.add(inst.display_name);
        instCount[inst.display_name] = (instCount[inst.display_name] ?? 0) + 1;
      }
    }
  }
}
const topInstitutions = Object.entries(instCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 6)
  .map(([name, count]) => ({ name, count }));

// Publicații pe an (ultimii 6 ani)
const groups = $('OpenAlex Trend').first().json.group_by ?? [];
const pubsPerYear = groups
  .map(t => ({ year: Number(String(t.key_display_name ?? t.key).trim()), count: t.count }))
  .filter(t => !Number.isNaN(t.year) && t.year >= 2020 && t.year <= $now.year)
  .sort((a, b) => a.year - b.year);

const cleanPapers = papers.map(p => ({
  title: p.title,
  year: p.publication_year,
  citations: p.cited_by_count,
  url: p.doi ?? p.id,
  abstract: rebuildAbstract(p.abstract_inverted_index).slice(0, 1500),
}));

// Semnale de industrie: articole cu cel puțin un autor din companie
const companyCount = {};
let papersWithIndustry = 0;
for (const p of papers) {
  const seen = new Set();
  for (const a of p.authorships ?? []) {
    for (const inst of a.institutions ?? []) {
      if (inst.type === 'company' && !seen.has(inst.display_name)) {
        seen.add(inst.display_name);
        companyCount[inst.display_name] = (companyCount[inst.display_name] ?? 0) + 1;
      }
    }
  }
  if (seen.size > 0) papersWithIndustry++;
}
const topCompanies = Object.entries(companyCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 8)
  .map(([name, count]) => ({ name, count }));
const industryShare = Math.round((100 * papersWithIndustry) / papers.length);

return [{
  json: {
    topic,
    paper_count: cleanPapers.length,
    pubs_per_year: pubsPerYear,
    top_institutions: topInstitutions,
    papers: cleanPapers,
    industry_share: industryShare,
    top_companies: topCompanies,
  },
}];

const d = $input.first().json;

const papers = d.papers
  .filter(p => p.abstract && p.abstract.length > 200)
  .slice(0, 12);

const context = papers
  .map((p, i) => `[${i + 1}] ${p.title} (${p.year}, ${p.citations} citations)\n${p.abstract.slice(0, 600)}`)
  .join('\n\n');

return [{
  json: {
    topic: d.topic.replace(/\b\w/g, c => c.toUpperCase()),
    trend: d.pubs_per_year
      .map(t => t.year === $now.year ? `${t.year} (partial year): ${t.count}` : `${t.year}: ${t.count}`)
      .join(', '),
    companies: d.top_companies.map(c => `${c.name} (${c.count})`).join(', ') || 'none found',
    industry_share: d.industry_share,
    institutions: d.top_institutions.map(i => `${i.name} (${i.count})`).join(', '),
    context,
    sources: papers.map((p, i) => ({ n: i + 1, title: p.title, url: p.url })),
  },
}];

const raw = $input.first().json.text ?? '';
const ctx = $('Build Context').first().json;

let brief = raw.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
brief += '\n\n' + ctx.sources.map(s => `[${s.n}] ${s.title} - ${s.url}`).join('\n');

const slug = ctx.topic.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

return [{ json: { topic: ctx.topic, brief, file_name: `${slug}.md` } }];
